import hashlib


def check_password(your_password):
    hash_ = "e9d36981609f2623858def80258e2e627ec3fe4c54deeee3bab480deba7a801e"
    hash_object = hashlib.sha256(your_password.encode('utf-8'))
    hash_result = hash_object.hexdigest()
    return hash_ == hash_result


def find_password():
    alphabet = "abcdefghijklmnopqrstuvwxyz0123456789"
    for a in alphabet:
        if check_password(a):
            return a
    for a in alphabet:
        for b in alphabet:
            candidate = a + b
            if check_password(candidate):
                return candidate
    for a in alphabet:
        for b in alphabet:
            for c in alphabet:
                candidate = a + b + c
                if check_password(candidate):
                    return candidate
    for a in alphabet:
        for b in alphabet:
            for c in alphabet:
                for d in alphabet:
                    candidate = a + b + c + d
                    if check_password(candidate):
                        return candidate
